from pathlib import Path
import re
p=Path('FINANCEIRO/index.html')
s=p.read_text()

# 1) live projection replaces imported projection in executive aggregates
s=s.replace("projection=data.official?.projection_monthly||[]","projection=data.planning?.live_projection||[]")

# 2) tabs
s=s.replace("const items=[['executiva','Visão Executiva'],['produtos','Produtos'],['capacidade','Capacidade'],['planejamento','Planejamento'],['valuation','Valuation'],['oficial','Base Oficial']]","const items=[['executiva','Visão Executiva'],['produtos','Produtos'],['capacidade','Capacidade'],['planejamento','Planejamento'],['valuation','Valuation'],['custos','Custos & Premissas'],['oficial','Base Importada']]")

# 3) settings writer helper after api()
api_pat=r"async function api\(\)\{.*?return j\}"
m=re.search(api_pat,s,flags=re.S)
if not m: raise SystemExit('api not found')
api_text=m.group(0)
if 'async function financeSetting' not in s:
    helper="""\nasync function financeSetting(payload){const sess=await YM.requireSession('/FINANCEIRO');if(!sess)throw new Error('Sessão necessária');const r=await fetch(YM.SUPABASE_URL+'/functions/v1/finance-settings',{method:'POST',headers:{Authorization:'Bearer '+sess.access_token,apikey:YM.PUBLISHABLE_KEY,'Content-Type':'application/json'},body:JSON.stringify(payload)});const j=await r.json().catch(()=>({}));if(!r.ok)throw new Error(j.detail||j.error||'Falha ao salvar');return j}\n"""
    s=s[:m.end()]+helper+s[m.end():]

# 4) Products panel - adds social media visibility and parameter status
new_products=r'''function productsPanel(){const p=data.products||[],bySale=[...p].sort((a,b)=>N(b.contribution_per_sale)-N(a.contribution_per_sale))[0],byHour=[...p].sort((a,b)=>N(b.contribution_per_hour)-N(a.contribution_per_hour))[0],byMargin=[...p].sort((a,b)=>N(b.margin)-N(a.margin))[0],attention=[...p].sort((a,b)=>N(a.margin)-N(b.margin))[0],alerts=data.economics_alerts||[];const alertBox=alerts.length?`<div class="section"><header><div><h2>Alertas de economia do produto</h2><p>Produtos com margem econômica abaixo de 20% usando os parâmetros atuais.</p></div>${badge(alerts.length+' alerta'+(alerts.length>1?'s':''),'warn')}</header><div class="section-body"><div class="scenario-grid">${alerts.map(x=>`<div class="scenario"><h3>${S(x.service_name)}</h3><p>${S(x.estimation_status||'HOMOLOGADO')} · margem ${PCT(x.margin)}</p><div class="minirow"><span>Contribuição/venda</span><b>${BRL(x.contribution_per_sale)}</b></div></div>`).join('')}</div><div class="source-note">Produtos marcados como ESTIMADO ainda dependem de medição real de horas. O alerta não muda preço automaticamente; apenas mostra o impacto econômico.</div></div></div>`:'';return `<div class="section-title">Produtos</div><p class="section-lead">Todos os produtos ativos entram aqui. Preço, horas e custo-hora alimentam Capacidade, Planejamento e Valuation em tempo real.</p><div class="insight-grid"><div class="insight"><div class="tag">Maior contribuição/venda</div><strong>${S(bySale?.service_name||'—')}</strong><span>${BRL(bySale?.contribution_per_sale)} por venda.</span></div><div class="insight"><div class="tag">Melhor contribuição/hora</div><strong>${S(byHour?.service_name||'—')}</strong><span>${BRL(byHour?.contribution_per_hour)} por hora.</span></div><div class="insight"><div class="tag">Maior margem</div><strong>${S(byMargin?.service_name||'—')}</strong><span>${PCT(byMargin?.margin)} de margem.</span></div><div class="insight"><div class="tag">Menor margem</div><strong>${S(attention?.service_name||'—')}</strong><span>${PCT(attention?.margin)} · atenção econômica.</span></div></div>${alertBox}<div class="section"><header><div><h2>Economia por produto</h2><p>Preço e horas do contrato completo. Para serviços recorrentes/multi-mês, a capacidade usa a carga mensal equivalente.</p></div></header><div class="section-body">${table([{label:'Produto'},{label:'Preço',money:true},{label:'Horas contrato',money:true},{label:'Custo entrega',money:true},{label:'Contribuição/venda',money:true},{label:'Contribuição/hora',money:true},{label:'Margem',money:true},{label:'Parâmetro'},{label:'Farol'}],p.map(x=>`<tr><td><strong>${S(x.service_name)}</strong></td><td class="money">${BRL(x.reference_price)}</td><td class="money">${N(x.human_hours).toLocaleString('pt-BR')}h</td><td class="money">${BRL(x.delivery_cost)}</td><td class="money"><strong>${BRL(x.contribution_per_sale)}</strong></td><td class="money">${BRL(x.contribution_per_hour)}</td><td class="money">${PCT(x.margin)}</td><td>${badge(x.estimation_status||'HOMOLOGADO',(x.estimation_status||'HOMOLOGADO')==='HOMOLOGADO'?'ok':'warn')}</td><td>${badge(x.farol,['PREJUIZO','CRITICO'].includes(x.farol)?'bad':x.farol==='ATENCAO'?'warn':'ok')}</td></tr>`))}</div></div>`}
function capacityPanel'''
s,n=re.subn(r"function productsPanel\(\)\{.*?\}\nfunction capacityPanel",new_products,s,count=1,flags=re.S)
if n!=1: raise SystemExit('products panel replace failed')

# 5) Capacity panel corrected to monthly hours/revenue for multi-month services
new_capacity=r'''function capacityPanel(){const s=data.summary||{},p=data.products||[],commitments=data.capacity_commitments||[],cur=data.current_month||{},f=data.commercial_snapshot||{};const safe=N(s.safe_delivery_hours||s.vendable_hours),committed=N(s.committed_hours),available=N(s.available_new_sales_hours),occupancy=N(s.capacity_occupancy_pct),freePct=Math.max(0,100-occupancy),target=N(s.monthly_revenue_target),contracted=N(cur.contratado),salesGap=Math.max(0,target-contracted),commercial=N(s.commercial_hours);const band=occupancy<40?'MUITO LIVRE':occupancy<65?'LIVRE':occupancy<80?'SAUDÁVEL':occupancy<90?'ALTA':'SATURADA';const bandNote=occupancy<40?'Seu gargalo hoje não é capacidade de entrega. Há espaço relevante para novos clientes.':occupancy<65?'Ainda há espaço confortável para crescer sem pressionar a operação.':occupancy<80?'A agenda está em faixa saudável; novas vendas precisam considerar o mix de produtos.':occupancy<90?'A capacidade está alta. Novas vendas precisam ser escolhidas pelo esforço de entrega.':'A operação está próxima do limite seguro.';const foundations=p.filter(x=>['FUNDACAO_ESSENCIAL','FUNDACAO_3_MESES','FUNDACAO_6_MESES'].includes(String(x.service_code))),slots=Math.max(0,10-commitments.length);const foundationCards=foundations.map(x=>{const q=Math.min(N(x.available_new_sales_capacity),slots),mh=N(x.monthly_hours_per_active||x.human_hours),mr=N(x.monthly_revenue_per_active||x.reference_price);return `<div class="insight"><div class="tag">SE TODO O SALDO FOSSE ESTE PRODUTO</div><strong>${q} ${S(x.service_name)}</strong><span>${mh.toLocaleString('pt-BR',{maximumFractionDigits:1})}h/mês por cliente ativo · ${BRL(q*mr)}/mês de receita equivalente. É capacidade comparativa, não meta.</span></div>`}).join('');const essential=foundations.find(x=>String(x.service_code)==='FUNDACAO_ESSENCIAL'),essentialPrice=N(essential?.monthly_revenue_per_active||essential?.reference_price),essentialHours=N(essential?.monthly_hours_per_active||essential?.human_hours),essentialToGap=essentialPrice>0?Math.ceil(salesGap/essentialPrice):0,gapHours=essentialToGap*essentialHours;const commercialStatus=salesGap<=0?'META CONTRATADA':occupancy<65?'MANTER 40H E ACELERAR CONVERSÃO':'PROTEGER ENTREGA';const commercialMessage=salesGap<=0?'A meta mensal já está coberta por contratos. O foco comercial pode migrar para os próximos meses.':occupancy<65?`Hoje faltam ${BRL(salesGap)} em contratos para a meta. Em Fundação Essencial isso equivale a ${essentialToGap} venda${essentialToGap===1?'':'s'} (${gapHours.toLocaleString('pt-BR')}h de entrega). Como há ${available.toLocaleString('pt-BR')}h livres, eu não aumentaria as ${commercial.toLocaleString('pt-BR')}h de prospecção agora; faria o funil avançar.`:'Antes de aumentar prospecção, proteja a entrega e priorize melhor contribuição/hora.';const funnelLine=N(f.total)>0?`O funil registra ${N(f.total)} oportunidades no histórico: ${N(f.reading_sent)} chegaram a leitura enviada, ${N(f.raiox_paid)} a Raio-X pago e ${N(f.won)} a ganho.`:'Ainda não há leitura comercial suficiente do funil para estimar conversão por hora.';const commitmentCards=commitments.map(x=>`<div class="scenario"><h3>${S(x.business_name)}</h3><p>${S(x.basis_label||'Estimativa operacional')}</p><div class="minirow"><span>Horas/mês estimadas</span><b>${N(x.estimated_hours_month).toLocaleString('pt-BR')}h</b></div><div class="minirow"><span>Status</span><b>${S(x.estimation_status)}</b></div></div>`).join('');return `<div class="section-title">Capacidade</div><p class="section-lead">Primeiro a notícia; depois a memória de cálculo.</p><div class="hero"><div class="hero-eyebrow">TERMÔMETRO DE OCUPAÇÃO ATUAL</div><h2>${band}: hoje você usa ${occupancy.toLocaleString('pt-BR',{maximumFractionDigits:1})}% da capacidade segura.</h2><div class="hero-value">${freePct.toLocaleString('pt-BR',{maximumFractionDigits:1})}% livre</div><div class="hero-label">${committed.toLocaleString('pt-BR')}h comprometidas de ${safe.toLocaleString('pt-BR')}h seguras para clientes.</div><div class="hero-progress"><span style="width:${Math.min(100,occupancy)}%"></span></div><div class="hero-progress-label">Ocupação: ${occupancy.toLocaleString('pt-BR',{maximumFractionDigits:1})}% · Livre: ${freePct.toLocaleString('pt-BR',{maximumFractionDigits:1})}%</div><div class="hero-metrics"><div class="hero-metric"><span>CLIENTES RECORRENTES SIMULADOS</span><b>${commitments.length}</b></div><div class="hero-metric"><span>HORAS AINDA VENDÁVEIS</span><b>${available.toLocaleString('pt-BR')}h</b></div><div class="hero-metric"><span>GAP PARA META DE ${BRL(target)}</span><b>${BRL(salesGap)}</b></div></div><div class="hero-note">${bandNote}</div></div><div class="section"><header><div><h2>O que isso significa em clientes?</h2><p>Para contratos de 3/6 meses, usamos horas e receita mensais por cliente ativo — não o contrato inteiro.</p></div>${badge(`${freePct.toLocaleString('pt-BR',{maximumFractionDigits:0})}% livre`,freePct>=35?'ok':freePct>=15?'warn':'bad')}</header><div class="section-body"><div class="insight-grid">${foundationCards}</div></div></div><div class="section"><header><div><h2>Notícia comercial do mês</h2><p>Capacidade × meta financeira × esforço de prospecção.</p></div>${badge(commercialStatus,salesGap<=0?'ok':occupancy<65?'warn':'neutral')}</header><div class="section-body"><div class="period-summary"><div class="summary-card emphasis"><strong>${commercialMessage}</strong><span>${funnelLine}</span></div><div class="summary-card"><strong>${commercial.toLocaleString('pt-BR')}h/mês de prospecção</strong><span>Cerca de ${(commercial/20).toLocaleString('pt-BR',{maximumFractionDigits:1})}h por dia útil. Antes de aumentar, medimos avanço e conversão.</span></div></div></div></div><div class="section"><header><div><h2>Como as 200h estão distribuídas</h2><p>Memória do termômetro.</p></div></header><div class="section-body"><div class="metric-grid"><div class="metric dark"><div class="k">Jornada mensal</div><div class="v">${N(s.total_hours||s.productive_hours).toLocaleString('pt-BR')}h</div></div><div class="metric"><div class="k">Prospecção / comercial</div><div class="v">${commercial.toLocaleString('pt-BR')}h</div></div><div class="metric"><div class="k">Gestão interna</div><div class="v">${N(s.management_hours).toLocaleString('pt-BR')}h</div></div><div class="metric indigo"><div class="k">Capacidade segura</div><div class="v">${safe.toLocaleString('pt-BR')}h</div></div><div class="metric orange"><div class="k">Já comprometidas</div><div class="v">${committed.toLocaleString('pt-BR')}h</div></div><div class="metric green"><div class="k">Livres para novas vendas</div><div class="v">${available.toLocaleString('pt-BR')}h</div></div></div></div></div><div class="section"><header><div><h2>Clientes já comprometidos</h2><p>Estimativas até medirmos tempo real.</p></div>${badge('ESTIMADO','warn')}</header><div class="section-body"><div class="scenario-grid">${commitmentCards}</div></div></div><div class="section"><header><div><h2>Equivalência completa por produto</h2><p>Capacidade mensal com o saldo atual. Em contratos longos, usamos o esforço mensal por cliente ativo.</p></div></header><div class="section-body">${table([{label:'Produto'},{label:'Horas/mês por ativo',money:true},{label:'Com saldo atual',money:true},{label:'Receita mensal equivalente',money:true},{label:'Parâmetro'}],p.map(x=>{const q=N(x.available_new_sales_capacity),mh=N(x.monthly_hours_per_active||x.human_hours),mr=N(x.monthly_revenue_per_active||x.reference_price);return `<tr><td><strong>${S(x.service_name)}</strong></td><td class="money">${mh.toLocaleString('pt-BR',{maximumFractionDigits:1})}h</td><td class="money"><strong>${q.toLocaleString('pt-BR')}</strong></td><td class="money">${BRL(q*mr)}</td><td>${badge(x.estimation_status||'HOMOLOGADO',(x.estimation_status||'HOMOLOGADO')==='HOMOLOGADO'?'ok':'warn')}</td></tr>`}))}</div></div>`}
function planningPanel'''
s,n=re.subn(r"function capacityPanel\(\)\{.*?\}\nfunction planningPanel",new_capacity,s,count=1,flags=re.S)
if n!=1: raise SystemExit('capacity panel replace failed')

# 6) Costs/settings panel + imported baseline
new_tail=r'''function costsPanel(){const sum=data.summary||{},costs=data.costs_all||[],ass=(data.assumptions_all||[]).filter(x=>x.editable===true&&x.active===true),estimated=(data.products||[]).filter(x=>(x.estimation_status||'HOMOLOGADO')!=='HOMOLOGADO'),types=['FIXO','COMERCIAL','IMPOSTO','VARIAVEL','OUTRO'];const costRows=costs.map(x=>`<tr><td><strong>${S(x.item_name)}</strong><div style="font-size:8px;color:#789">${S(x.item_code)}</div></td><td><select id="ct_${S(x.item_code)}" style="width:100%;padding:7px;border:1px solid #D5E0E8;border-radius:8px">${types.map(t=>`<option ${x.cost_type===t?'selected':''}>${t}</option>`).join('')}</select></td><td><input id="cv_${S(x.item_code)}" type="number" step="0.01" min="0" value="${N(x.monthly_value)}" style="width:105px;padding:7px;border:1px solid #D5E0E8;border-radius:8px"></td><td style="text-align:center"><input id="ca_${S(x.item_code)}" type="checkbox" ${x.active?'checked':''}></td><td><button class="ym-btn secondary" onclick="saveCost('${S(x.item_code)}','${S(x.item_name).replace(/'/g,"&#39;")}')">Salvar</button></td></tr>`);const assRows=ass.map(x=>`<tr><td><strong>${S(x.label)}</strong><div style="font-size:8px;color:#789">${S(x.assumption_key)}</div></td><td>${S(x.unit||'—')}</td><td><input id="av_${S(x.assumption_key)}" type="number" step="0.01" value="${N(x.numeric_value)}" style="width:120px;padding:7px;border:1px solid #D5E0E8;border-radius:8px"></td><td><button class="ym-btn secondary" onclick="saveAssumption('${S(x.assumption_key)}')">Salvar</button></td></tr>`);const prodRows=estimated.map(x=>`<tr><td><strong>${S(x.service_name)}</strong><div style="font-size:8px;color:#789">${S(x.service_code)}</div></td><td><input id="ph_${S(x.service_code)}" type="number" step="0.5" min="0" value="${N(x.human_hours)}" style="width:90px;padding:7px;border:1px solid #D5E0E8;border-radius:8px"></td><td><input id="pp_${S(x.service_code)}" type="number" step="1" min="0" value="${N(x.reference_price)}" style="width:100px;padding:7px;border:1px solid #D5E0E8;border-radius:8px"></td><td>${PCT(x.margin)}</td><td><button class="ym-btn secondary" onclick="saveProduct('${S(x.service_code)}')">Salvar</button></td></tr>`);return `<div class="section-title">Custos & Premissas</div><p class="section-lead">Esta é a área operacional do modelo. Alterou custo, hora, meta ou parâmetro estimado? Ao salvar, todas as leituras vivas recalculam.</p><div class="metric-grid"><div class="metric dark"><div class="k">Custos em dinheiro / mês</div><div class="v">${BRL(sum.cash_cost_monthly)}</div><div class="d">Itens ativos na competência atual.</div></div><div class="metric"><div class="k">Custo econômico comercial</div><div class="v">${BRL(sum.commercial_economic_cost)}</div><div class="d">Valor das horas reservadas para vender.</div></div><div class="metric"><div class="k">Custo econômico de gestão</div><div class="v">${BRL(sum.management_economic_cost)}</div><div class="d">Tempo de gestão/financeiro/CRM.</div></div><div class="metric indigo"><div class="k">Base econômica mensal</div><div class="v">${BRL(sum.economic_base_monthly)}</div><div class="d">Caixa + tempo comercial + gestão.</div></div></div><div class="section"><header><div><h2>Adicionar custo</h2><p>Ex.: nova ferramenta, assinatura, imposto, mídia ou despesa operacional.</p></div></header><div class="section-body"><div style="display:grid;grid-template-columns:2fr 1fr 1fr 2fr auto;gap:8px;align-items:end"><label style="font-size:9px">Nome<input id="newCostName" style="display:block;width:100%;box-sizing:border-box;margin-top:4px;padding:9px;border:1px solid #D5E0E8;border-radius:9px"></label><label style="font-size:9px">Valor/mês<input id="newCostValue" type="number" min="0" step="0.01" style="display:block;width:100%;box-sizing:border-box;margin-top:4px;padding:9px;border:1px solid #D5E0E8;border-radius:9px"></label><label style="font-size:9px">Tipo<select id="newCostType" style="display:block;width:100%;margin-top:4px;padding:9px;border:1px solid #D5E0E8;border-radius:9px">${types.map(t=>`<option>${t}</option>`).join('')}</select></label><label style="font-size:9px">Observação<input id="newCostNotes" style="display:block;width:100%;box-sizing:border-box;margin-top:4px;padding:9px;border:1px solid #D5E0E8;border-radius:9px"></label><button class="ym-btn" onclick="addCost()">Adicionar</button></div></div></div><div class="section"><header><div><h2>Custos atuais</h2><p>Desative um item se ele deixar de existir; não apague a memória.</p></div>${badge('EDITÁVEL','ok')}</header><div class="section-body">${table([{label:'Custo'},{label:'Tipo'},{label:'Valor mensal'},{label:'Ativo'},{label:'Ação'}],costRows)}</div></div><div class="section"><header><div><h2>Premissas que dirigem os cálculos</h2><p>Horas, custo-hora, reserva, metas e múltiplos. Alterações afetam o modelo imediatamente.</p></div>${badge('EDITÁVEL','ok')}</header><div class="section-body">${table([{label:'Premissa'},{label:'Unidade'},{label:'Valor'},{label:'Ação'}],assRows)}</div></div>${estimated.length?`<div class="section"><header><div><h2>Produtos ainda em medição</h2><p>Os pacotes de Social Media entram no modelo, mas as horas estão sinalizadas como estimativa até medirmos execução real.</p></div>${badge('ESTIMADO','warn')}</header><div class="section-body">${table([{label:'Produto'},{label:'Horas/mês'},{label:'Preço'},{label:'Margem atual'},{label:'Ação'}],prodRows)}</div></div>`:''}`}
async function saveCost(code,name){try{await financeSetting({action:'UPSERT_COST',item_code:code,item_name:name,monthly_value:N($('cv_'+code).value),cost_type:$('ct_'+code).value,active:$('ca_'+code).checked,reason:'Atualização manual em Custos & Premissas'});YM.toast('Custo atualizado');await load()}catch(e){YM.toast(e.message,true)}}
async function addCost(){try{const name=$('newCostName').value.trim(),value=N($('newCostValue').value);if(!name)throw new Error('Informe o nome do custo');await financeSetting({action:'UPSERT_COST',item_name:name,monthly_value:value,cost_type:$('newCostType').value,notes:$('newCostNotes').value,active:true,reason:'Novo custo incluído no Financeiro'});YM.toast('Custo incluído');await load()}catch(e){YM.toast(e.message,true)}}
async function saveAssumption(key){try{await financeSetting({action:'UPDATE_ASSUMPTION',assumption_key:key,numeric_value:N($('av_'+key).value),reason:'Premissa atualizada no Financeiro'});YM.toast('Premissa atualizada');await load()}catch(e){YM.toast(e.message,true)}}
async function saveProduct(code){try{await financeSetting({action:'UPDATE_PRODUCT',service_code:code,human_hours:N($('ph_'+code).value),reference_price:N($('pp_'+code).value),estimation_status:'ESTIMADO',reason:'Parâmetro estimado atualizado no Financeiro'});YM.toast('Produto atualizado');await load()}catch(e){YM.toast(e.message,true)}}
function officialPanel(){const o=data.baseline||{},ass=data.assumptions_all||[],costs=data.costs_all||[],p=data.products||[],sc=o.scenarios||[],proj=o.projection_monthly||[],roi=o.roi_monthly||[],val=o.valuation||[],kpi=o.dashboard_kpis||[],pay=o.dashboard_payback||[];return `<div class="source-box"><strong>BASE IMPORTADA · YM_Quadro_Financeiro_ROI_Valuation_COMPLETO.xlsx</strong><p>Snapshot para memória e auditoria. Estes números importados NÃO alimentam mais as decisões das outras abas. O modelo vivo usa CRM + custos + premissas + produtos atuais.</p></div><details class="sheet"><summary>Dashboard importado</summary><div class="sheet-body">${table([{label:'Indicador'},{label:'Valor',money:true},{label:'Unidade'}],kpi.map(x=>`<tr><td><strong>${S(x.label)}</strong></td><td class="money">${N(x.numeric_value).toLocaleString('pt-BR')}</td><td>${S(x.unit||'—')}</td></tr>`),'520px')}${table([{label:'Produto'},{label:'Contribuição/venda',money:true},{label:'Vendas p/ investimento',money:true}],pay.map(x=>`<tr><td><strong>${S(x.service_name)}</strong></td><td class="money">${BRL(x.contribution_per_sale)}</td><td class="money">${N(x.sales_to_recover_23000).toLocaleString('pt-BR')}</td></tr>`),'520px')}</div></details><details class="sheet"><summary>Premissas atuais</summary><div class="sheet-body">${table([{label:'Premissa'},{label:'Categoria'},{label:'Valor'},{label:'Unidade'},{label:'Fonte'}],ass.map(x=>`<tr><td><strong>${S(x.label)}</strong></td><td>${S(x.category)}</td><td>${N(x.numeric_value).toLocaleString('pt-BR')}</td><td>${S(x.unit||'—')}</td><td>${S(x.source_note||'—')}</td></tr>`))}</div></details><details class="sheet"><summary>Custos atuais</summary><div class="sheet-body">${table([{label:'Item'},{label:'Tipo'},{label:'Mensal',money:true},{label:'Ativo'}],costs.map(x=>`<tr><td><strong>${S(x.item_name)}</strong></td><td>${S(x.cost_type)}</td><td class="money">${BRL(x.monthly_value)}</td><td>${x.active?'Sim':'Não'}</td></tr>`),'620px')}</div></details><details class="sheet"><summary>Produtos vivos</summary><div class="sheet-body">${table([{label:'Produto'},{label:'Preço',money:true},{label:'Horas',money:true},{label:'Contribuição',money:true},{label:'Margem',money:true},{label:'Parâmetro'}],p.map(x=>`<tr><td><strong>${S(x.service_name)}</strong></td><td class="money">${BRL(x.reference_price)}</td><td class="money">${N(x.human_hours).toLocaleString('pt-BR')}</td><td class="money">${BRL(x.contribution_per_sale)}</td><td class="money">${PCT(x.margin)}</td><td>${S(x.estimation_status||'HOMOLOGADO')}</td></tr>`))}</div></details><details class="sheet"><summary>Visão Geral importada</summary><div class="sheet-body">${table([{label:'Cenário'},{label:'Mix'},{label:'Receita',money:true},{label:'Resultado econômico',money:true},{label:'Capacidade'}],sc.map(x=>`<tr><td><strong>${S(x.scenario_name)}</strong></td><td>${S(x.mix_monthly)}</td><td class="money">${BRL(x.revenue)}</td><td class="money">${BRL(x.economic_result)}</td><td>${S(x.capacity_status)}</td></tr>`))}</div></details><details class="sheet"><summary>Projeção Mensal importada</summary><div class="sheet-body">${table([{label:'Mês'},{label:'Receita planejada',money:true},{label:'Resultado econômico',money:true},{label:'Capacidade'}],proj.map(x=>`<tr><td><strong>${MONTH(x.month)}</strong></td><td class="money">${BRL(x.planned_revenue)}</td><td class="money">${BRL(x.economic_result)}</td><td>${S(x.status)}</td></tr>`))}</div></details><details class="sheet"><summary>ROI importado</summary><div class="sheet-body">${table([{label:'Mês'},{label:'Receita',money:true},{label:'Resultado econômico',money:true},{label:'ROI acumulado',money:true}],roi.map(x=>`<tr><td><strong>${MONTH(x.month)}</strong></td><td class="money">${BRL(x.revenue)}</td><td class="money">${BRL(x.economic_result)}</td><td class="money">${PCT(x.accumulated_roi)}</td></tr>`))}</div></details><details class="sheet"><summary>Valuation importado</summary><div class="sheet-body">${table([{label:'Indicador'},{label:'Fórmula / premissa'},{label:'Valor',money:true},{label:'Observação'}],val.map(x=>`<tr><td><strong>${S(x.indicator)}</strong></td><td>${S(x.formula_premise)}</td><td class="money">${BRL(x.numeric_value)}</td><td>${S(x.observation||'—')}</td></tr>`))}</div></details>`}
function render'''
s,n=re.subn(r"function officialPanel\(\)\{.*?\}\nfunction render",new_tail,s,count=1,flags=re.S)
if n!=1: raise SystemExit('tail replace failed')

# 7) render routing and status
s=s.replace("state.tab==='valuation'?valuationPanel():officialPanel()","state.tab==='valuation'?valuationPanel():state.tab==='custos'?costsPanel():officialPanel()")
s=s.replace("ARQUITETURA VALIDADA · dados atualizados para conferência","CÁLCULOS VIVOS · custos e premissas editáveis")

p.write_text(s)
print('patched',len(s))
